import argparse
import json

from .models import MergeResult, NotificationReason
from .notification_text import format_notification
from .state import compact_state


def write_outputs(args: argparse.Namespace, state: dict, reasons: list[NotificationReason]) -> None:
    if args.state_output:
        args.state_output.write_text(
            json.dumps(compact_state(state), indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )

    notification = {
        "notify": bool(reasons),
        "reasons": [reason.value for reason in reasons],
        "status": state["status"],
        "text": format_notification(state, reasons, "slack") if reasons else "",
        "slack_text": format_notification(state, reasons, "slack") if reasons else "",
        "zulip_text": format_notification(state, reasons, "zulip") if reasons else "",
        "state": state,
    }

    if args.notification_output:
        args.notification_output.write_text(
            json.dumps(notification, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )

    if args.github_output:
        with args.github_output.open("a", encoding="utf-8") as output:
            output.write(f"status={state['status']}\n")
            output.write(f"should_notify={'true' if reasons else 'false'}\n")
            output.write(f"health_fingerprint={state['health_fingerprint']}\n")


def print_result(result: MergeResult) -> None:
    print()
    print(f"Merge check: {result.source_label} -> {result.target}")
    print("-" * 72)
    print(f"Status: {result.status}")
    print(result.message)

    if result.conflicted_files:
        print()
        print("Conflicted files:")
        for path in result.conflicted_files:
            print(f"  - {path}")

    if result.conflict_origins:
        print()
        print("Source-side commits where the conflicted files start to conflict:")
        for origin in result.conflict_origins:
            if origin.from_test_merge:
                print("  - unmerged changes from earlier branches")
            elif origin.commit:
                c = origin.commit
                print(f"  - {c.sha}")
                print(f"    Author:  {c.author}")
                print(f"    Subject: {c.subject}")
            else:
                print("  - not identified")
            for c in origin.via_commits:
                print(f"    Via:     {c.sha[:12]} {c.subject} ({c.author})")
            for path in origin.files:
                print(f"    File:    {path}")

    if result.candidate_commits:
        print()
        print("Candidate commits touching conflicted files:")
        side_labels = {
            "source": f"Source side ({result.source_label})",
            "target": f"Target side ({result.target})",
            "unknown": "Unknown side",
        }
        for side in ["source", "target", "unknown"]:
            commits = [
                commit for commit in result.candidate_commits if commit.side == side
            ]
            if not commits:
                continue

            print(f"  {side_labels[side]}:")
            for c in commits:
                print(f"    - {c.sha}")
                print(f"      Author:  {c.author}")
                print(f"      Subject: {c.subject}")


def print_summary(results: list[MergeResult]) -> None:
    print()
    print("=" * 72)
    print("Summary")
    print("=" * 72)

    if not results:
        print("No forward branches to check.")
        print("Final result: forward merge chain is clean.")
        return

    for result in results:
        print(f"{result.source_label} -> {result.target}: {result.status}")

    print()

    if any(result.status == "conflict" for result in results):
        print("Final result: forward merge chain is blocked by conflicts.")
    else:
        print("Final result: forward merge chain is clean or already merged.")

import shutil
import subprocess
import tempfile
from pathlib import Path
from typing import Optional

from .models import CommitInfo


def run(
    args: list[str],
    cwd: Optional[Path] = None,
    check: bool = True,
    capture: bool = True,
) -> subprocess.CompletedProcess:
    proc = subprocess.run(
        args,
        cwd=cwd,
        text=True,
        stdout=subprocess.PIPE if capture else None,
        stderr=subprocess.PIPE if capture else None,
    )

    if check and proc.returncode != 0:
        raise RuntimeError(
            f"Command failed: {' '.join(args)}\n"
            f"exit code: {proc.returncode}\n"
            f"stdout:\n{proc.stdout or ''}\n"
            f"stderr:\n{proc.stderr or ''}"
        )

    return proc


def git(repo: Path, args: list[str], check: bool = True) -> subprocess.CompletedProcess:
    return run(["git", *args], cwd=repo, check=check)


def remote_ref(branch: str) -> str:
    return f"refs/remotes/origin/{branch}"


def local_ref(branch: str) -> str:
    return f"refs/heads/{branch}"


def ensure_ref(repo: Path, ref: str) -> None:
    git(repo, ["rev-parse", "--verify", "--quiet", ref])


def has_ref(repo: Path, ref: str) -> bool:
    proc = git(repo, ["rev-parse", "--verify", "--quiet", ref], check=False)
    return proc.returncode == 0


def branch_ref(repo: Path, branch: str) -> Optional[str]:
    if has_ref(repo, remote_ref(branch)):
        return remote_ref(branch)
    if has_ref(repo, local_ref(branch)):
        return local_ref(branch)
    return None


def require_branch_ref(repo: Path, branch: str) -> str:
    ref = branch_ref(repo, branch)
    if ref is None:
        raise ValueError(format_missing_branch_refs_error(repo, [branch], [branch]))
    return ref


def missing_branch_refs(repo: Path, branches: list[str]) -> list[str]:
    return [branch for branch in branches if branch_ref(repo, branch) is None]


def format_missing_branch_refs_error(repo: Path, branches: list[str], missing: list[str]) -> str:
    configured = "\n".join(f"  - {branch}" for branch in branches)
    fetch_lines = " \\\n  ".join(
        f"+refs/heads/{branch}:refs/remotes/origin/{branch}" for branch in missing
    )

    return (
        "The target repository is missing configured branch refs.\n\n"
        f"Target repository: {repo}\n\n"
        "Configured branch chain:\n"
        f"{configured}\n\n"
        "Missing branch refs:\n"
        + "\n".join(
            f"  - {remote_ref(branch)} or {local_ref(branch)}" for branch in missing
        )
        + "\n\n"
        "Fetch the missing remote-tracking refs into the target repository:\n\n"
        f"git -C {repo} fetch origin \\\n"
        f"  {fetch_lines}\n\n"
        "For local-only testing, local branches with the configured names also work.\n\n"
        "If one of these branches no longer exists, update the configured chain "
        "instead of fetching it."
    )


def ensure_branch_refs(repo: Path, branches: list[str]) -> None:
    missing = missing_branch_refs(repo, branches)
    if missing:
        raise ValueError(format_missing_branch_refs_error(repo, branches, missing))


def is_ancestor(repo: Path, maybe_ancestor: str, descendant: str) -> bool:
    proc = git(
        repo,
        ["merge-base", "--is-ancestor", maybe_ancestor, descendant],
        check=False,
    )
    return proc.returncode == 0


COMMIT_INFO_FORMAT = "%H%x00%an <%ae>%x00%s"


def parse_commit_info(line: str) -> CommitInfo:
    commit_sha, author, subject = line.split("\x00", 2)
    return CommitInfo(sha=commit_sha, author=author, subject=subject)


def get_commit_info(repo: Path, sha: str) -> CommitInfo:
    proc = git(repo, ["show", "-s", f"--format={COMMIT_INFO_FORMAT}", sha])
    return parse_commit_info(proc.stdout.rstrip("\n"))


def is_merge_commit(repo: Path, sha: str) -> bool:
    parents = git(repo, ["show", "-s", "--format=%P", sha]).stdout.split()
    return len(parents) > 1


def commits_brought_in_by_merge(repo: Path, merge_sha: str, paths: list[str]) -> list[CommitInfo]:
    proc = git(
        repo,
        [
            "log",
            "--no-merges",
            f"--format={COMMIT_INFO_FORMAT}",
            f"{merge_sha}^1..{merge_sha}",
            "--",
            *paths,
        ],
    )
    return [parse_commit_info(line) for line in proc.stdout.splitlines() if line]


def merge_tree_conflicted_files(repo: Path, ours: str, theirs: str) -> list[str]:
    """
    Merge in memory with `git merge-tree --write-tree` (git 2.38+), without a
    worktree or checkout, and return the conflicted paths.
    """
    proc = git(
        repo,
        ["merge-tree", "--write-tree", "--name-only", "--no-messages", "-z", ours, theirs],
        check=False,
    )
    # Exit code 0 is a clean merge and 1 is a merge with conflicts.
    if proc.returncode not in (0, 1):
        raise RuntimeError(
            f"git merge-tree failed for {ours} and {theirs}\n"
            f"exit code: {proc.returncode}\n"
            f"stderr:\n{proc.stderr or ''}"
        )

    # The output is the merged tree id, then one entry per conflicted path.
    return [path for path in proc.stdout.split("\0")[1:] if path]


def branch_head(repo: Path, branch: str) -> str:
    return git(repo, ["rev-parse", require_branch_ref(repo, branch)]).stdout.strip()


def add_worktree(repo: Path, ref: str, scratch_root: Path) -> Path:
    worktree = Path(tempfile.mkdtemp(prefix="merge-check-", dir=scratch_root))
    shutil.rmtree(worktree)
    git(repo, ["worktree", "add", "--detach", "--quiet", str(worktree), ref])
    git(worktree, ["config", "user.name", "Forward Mergeability Checker"])
    git(worktree, ["config", "user.email", "forward-mergeability@example.invalid"])
    return worktree


def remove_worktree(repo: Path, worktree: Path) -> None:
    git(repo, ["worktree", "remove", "--force", str(worktree)], check=False)


def get_conflicted_files(worktree: Path) -> list[str]:
    proc = git(worktree, ["diff", "--name-only", "--diff-filter=U"])
    return [line.strip() for line in proc.stdout.splitlines() if line.strip()]

import os
from typing import Optional

from .models import NotificationReason

MAX_VIA_COMMITS = 5

def github_repository_label() -> str:
    return (
        os.environ.get("FORWARD_MERGE_TARGET_REPOSITORY")
        or os.environ.get("GITHUB_REPOSITORY")
        or "unknown repository"
    )


def repository_url(repository: str) -> str:
    server_url = os.environ.get("GITHUB_SERVER_URL", "https://github.com").rstrip("/")
    return f"{server_url}/{repository}"


def github_repository_url() -> Optional[str]:
    repository = (
        os.environ.get("FORWARD_MERGE_TARGET_REPOSITORY")
        or os.environ.get("GITHUB_REPOSITORY")
    )
    if not repository:
        return None

    return repository_url(repository)


def github_workflow_repository_url() -> Optional[str]:
    repository = os.environ.get("GITHUB_REPOSITORY")
    if not repository:
        return None

    return repository_url(repository)


def github_action_run_url() -> Optional[str]:
    repository_url = github_workflow_repository_url()
    run_id = os.environ.get("GITHUB_RUN_ID")
    if not repository_url or not run_id:
        return None

    return f"{repository_url}/actions/runs/{run_id}"


def github_commit_url(sha: str) -> Optional[str]:
    repository_url = github_repository_url()
    if not repository_url:
        return None

    return f"{repository_url}/commit/{sha}"


def format_link(url: Optional[str], label: str, style: str) -> str:
    if not url:
        return label
    if style == "zulip":
        return f"[{label}]({url})"
    return f"<{url}|{label}>"


def humanize_notification_reasons(reasons: list[NotificationReason]) -> str:
    labels = {
        NotificationReason.FIRST_RUN: "first observed broken state",
        NotificationReason.BROKEN: "chain became blocked",
        NotificationReason.RESOLVED: "chain recovered",
        NotificationReason.HEALTH_CHANGED: "blocked result changed",
        NotificationReason.CHAIN_CHANGED: "configured chain changed",
    }
    return ", ".join(labels.get(reason, reason.value) for reason in reasons)


def result_status_label(status: str) -> str:
    labels = {
        "merge_ok": "merged cleanly",
        "nothing_to_merge": "already contained",
        "conflict": "conflict",
        "skipped": "skipped",
    }
    return labels.get(status, status)


def result_status_icon(status: str) -> str:
    if status == "conflict":
        return "❌"
    if status in {"merge_ok", "nothing_to_merge"}:
        return "✅"
    return "⚪"


def format_notification(state: dict, reasons: list[NotificationReason], style: str = "slack") -> str:
    status_text = "✅ healthy"
    if state["status"] == "broken":
        status_text = "🚨 blocked"

    lines = [
        "*Forward Merge Checker*",
        "",
        f"- *Status:* {status_text}",
        f"- *Repository:* `{github_repository_label()}`",
    ]

    if reasons:
        lines.append(f"- *Reason:* {humanize_notification_reasons(reasons)}")

    indexed_results = list(enumerate(state["results"], start=1))
    blocked_results = [
        (index, result) for index, result in indexed_results if result["status"] == "conflict"
    ]
    if blocked_results:
        blocked_edges = ", ".join(
            f"{index}. `{result['source_label']}` -> `{result['target']}`"
            for index, result in blocked_results
        )
        lines.append(f"- *Blocked edges ({len(blocked_results)}):* {blocked_edges}")

    lines.append(f"- *Chain:* {' -> '.join(f'`{branch}`' for branch in state['branches'])}")

    action_run_url = github_action_run_url()
    if action_run_url:
        lines.append(f"- *GitHub Actions run:* {format_link(action_run_url, 'open run', style)}")

    if indexed_results:
        lines.append("")
        lines.append("*Checked edges:*")
        for index, result in indexed_results:
            lines.append(
                f"{index}. {result_status_icon(result['status'])} "
                f"`{result['source_label']}` -> `{result['target']}`: "
                f"{result_status_label(result['status'])}"
            )

    if blocked_results:
        lines.append("")
        lines.append("*Conflict details:*")

    for index, blocked in blocked_results:
        lines.append("")
        lines.append(f"{index}. *Edge:* `{blocked['source_label']}` -> `{blocked['target']}`")

        if not blocked["conflicted_files"]:
            continue

        lines.append(f"*Conflicted files ({len(blocked['conflicted_files'])}):*")
        origins = blocked.get("conflict_origins") or []
        if not origins:
            lines.extend(format_file_block(blocked["conflicted_files"]))
        for origin in origins:
            lines.extend(format_conflict_origin(origin, style))

    return "\n".join(lines)


def format_commit(commit: dict, style: str) -> str:
    label = format_link(github_commit_url(commit["sha"]), commit["sha"][:12], style)
    return f"{label} - {commit['subject']}"


def format_file_block(files: list[str]) -> list[str]:
    return ["```", *(f"- {path}" for path in files), "```"]


def format_conflict_origin(origin: dict, style: str) -> list[str]:
    commit = origin.get("commit")
    via_commits = origin.get("via_commits") or []

    if origin.get("from_test_merge"):
        lines = ["*Started conflicting at:* unmerged changes from earlier branches"]
    elif commit:
        lines = [f"*Started conflicting at:* {format_commit(commit, style)}"]
        # A merge that brought the change in did not author it.
        author_label = "Merged by" if via_commits else "Author"
        lines.append(f"*{author_label}:* {commit['author']}")
    else:
        lines = ["*Started conflicting at:* not identified"]

    if via_commits:
        lines.append("*Changes brought in that touch these files:*")
        lines.extend(
            f"- {format_commit(via, style)} ({via['author']})"
            for via in via_commits[:MAX_VIA_COMMITS]
        )
        if len(via_commits) > MAX_VIA_COMMITS:
            lines.append(f"- and {len(via_commits) - MAX_VIA_COMMITS} more")

    lines.extend(format_file_block(origin["files"]))
    return lines

import hashlib
import json
from datetime import datetime, timezone
from pathlib import Path
from typing import Optional

from .git_ops import branch_head
from .models import CommitInfo, ConflictCommit, ConflictOrigin, MergeResult, NotificationReason


def commit_to_dict(commit: Optional[CommitInfo]) -> Optional[dict]:
    if commit is None:
        return None
    return {
        "sha": commit.sha,
        "author": commit.author,
        "subject": commit.subject,
    }


def conflict_origin_to_dict(origin: ConflictOrigin) -> dict:
    return {
        "files": origin.files,
        "commit": commit_to_dict(origin.commit),
        "via_commits": [commit_to_dict(commit) for commit in origin.via_commits],
        "from_test_merge": origin.from_test_merge,
    }


def conflict_commit_to_dict(commit: ConflictCommit) -> dict:
    return {
        "side": commit.side,
        "sha": commit.sha,
        "author": commit.author,
        "subject": commit.subject,
    }


def result_to_dict(result: MergeResult) -> dict:
    return {
        "source_label": result.source_label,
        "source_ref": result.source_ref,
        "target": result.target,
        "status": result.status,
        "message": result.message,
        "conflicted_files": result.conflicted_files,
        "conflict_origins": [
            conflict_origin_to_dict(origin) for origin in result.conflict_origins
        ],
        "candidate_commits": [
            conflict_commit_to_dict(commit) for commit in result.candidate_commits
        ],
    }


def stable_json(value: object) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"))


def fingerprint(value: object) -> str:
    return hashlib.sha256(stable_json(value).encode("utf-8")).hexdigest()


def current_state(repo: Path, branches: list[str], base_branch: str, results: list[MergeResult]) -> dict:
    branch_heads = {branch: branch_head(repo, branch) for branch in branches}
    blocked = next((result for result in results if result.status == "conflict"), None)
    status = "broken" if blocked else "healthy"

    config_payload = {
        "branches": branches,
        "base_branch": base_branch,
    }
    health_payload = {
        "status": status,
        "blocked_edge": None if blocked is None else [blocked.source_label, blocked.target],
        "conflicted_files": [] if blocked is None else blocked.conflicted_files,
        # Via commits are left out: for a test merge they grow with every new
        # commit on the earlier branches, which is not a health change.
        "conflict_origins": []
        if blocked is None
        else [
            {
                "files": origin.files,
                "commit": None if origin.commit is None else origin.commit.sha,
                "from_test_merge": origin.from_test_merge,
            }
            for origin in blocked.conflict_origins
        ],
        "results": [
            {
                "target": result.target,
                "status": result.status,
                "conflicted_files": result.conflicted_files,
            }
            for result in results
        ],
    }

    return {
        "version": 1,
        "checked_at": datetime.now(timezone.utc).isoformat(),
        "status": status,
        "base_branch": base_branch,
        "branches": branches,
        "branch_heads": branch_heads,
        "config_fingerprint": fingerprint(config_payload),
        "health_fingerprint": fingerprint(health_payload),
        "results": [result_to_dict(result) for result in results],
    }


def load_previous_state(raw_state: str | None) -> Optional[dict]:
    if not raw_state:
        return None

    try:
        parsed = json.loads(raw_state)
    except json.JSONDecodeError:
        return None

    return parsed if isinstance(parsed, dict) else None


def load_previous_state_file(path: Optional[Path]) -> Optional[dict]:
    if path is None or not path.exists():
        return None

    return load_previous_state(path.read_text(encoding="utf-8"))


def notification_reasons(previous: Optional[dict], state: dict) -> list[NotificationReason]:
    if previous is None:
        return [NotificationReason.FIRST_RUN] if state["status"] == "broken" else []

    reasons: list[NotificationReason] = []

    if previous.get("config_fingerprint") != state.get("config_fingerprint"):
        reasons.append(NotificationReason.CHAIN_CHANGED)

    old_status = previous.get("status")
    new_status = state.get("status")

    if old_status != "broken" and new_status == "broken":
        reasons.append(NotificationReason.BROKEN)
    elif old_status == "broken" and new_status != "broken":
        reasons.append(NotificationReason.RESOLVED)
    elif old_status == "broken" and new_status == "broken":
        if previous.get("health_fingerprint") != state.get("health_fingerprint"):
            reasons.append(NotificationReason.HEALTH_CHANGED)

    return reasons


def compact_state(state: dict) -> dict:
    return {
        "version": state["version"],
        "checked_at": state["checked_at"],
        "status": state["status"],
        "base_branch": state["base_branch"],
        "branches": state["branches"],
        "branch_heads": state["branch_heads"],
        "config_fingerprint": state["config_fingerprint"],
        "health_fingerprint": state["health_fingerprint"],
        "results": [
            {
                "source_label": result["source_label"],
                "target": result["target"],
                "status": result["status"],
                "conflicted_files": result["conflicted_files"],
                "conflict_origins": [
                    {
                        "files": origin["files"],
                        "commit": None
                        if origin["commit"] is None
                        else {
                            "sha": origin["commit"]["sha"],
                            "subject": origin["commit"]["subject"],
                        },
                        "via_commits": [commit["sha"] for commit in origin["via_commits"]],
                        "from_test_merge": origin["from_test_merge"],
                    }
                    for origin in result["conflict_origins"]
                ],
            }
            for result in state["results"]
        ],
    }

import argparse
import os
from pathlib import Path


DEFAULT_BRANCHES = ["10.6", "10.11", "11.4", "11.8", "12.3", "main"]
DEFAULT_CONFIG_FILE = Path(".github/forward-merge-check/repositories/mariadb-server.yml")
LEGACY_BRANCH_FILE = Path(".github/forward-merge-branches.txt")


def parse_scalar(value: str) -> object:
    value = value.strip()

    if value in {"true", "True"}:
        return True
    if value in {"false", "False"}:
        return False
    if value in {"null", "Null", "~"}:
        return None
    if (value.startswith('"') and value.endswith('"')) or (
        value.startswith("'") and value.endswith("'")
    ):
        return value[1:-1]
    return value


def read_simple_yaml(path: Path) -> dict:
    """
    Parse the tiny YAML subset used by repository config files.

    Supported forms:
      key: value
      parent:
        child: value
      list:
        - value
    """
    root: dict = {}
    stack: list[tuple[int, dict | list]] = [(-1, root)]
    pending_key: tuple[int, dict, str] | None = None

    for line_number, raw_line in enumerate(path.read_text(encoding="utf-8").splitlines(), start=1):
        if not raw_line.strip() or raw_line.lstrip().startswith("#"):
            continue

        indent = len(raw_line) - len(raw_line.lstrip(" "))
        stripped = raw_line.strip()

        while stack and indent <= stack[-1][0]:
            stack.pop()

        if pending_key and indent > pending_key[0]:
            parent_indent, parent, key = pending_key
            container: dict | list = [] if stripped.startswith("- ") else {}
            parent[key] = container
            stack.append((parent_indent, container))
            pending_key = None

        parent = stack[-1][1]

        if stripped.startswith("- "):
            if not isinstance(parent, list):
                raise ValueError(f"{path}:{line_number}: list item outside a list")
            parent.append(parse_scalar(stripped[2:]))
            continue

        if ":" not in stripped:
            raise ValueError(f"{path}:{line_number}: expected 'key: value'")

        key, value = stripped.split(":", 1)
        key = key.strip()
        value = value.strip()

        if not isinstance(parent, dict):
            raise ValueError(f"{path}:{line_number}: mapping item outside a mapping")

        if value:
            parent[key] = parse_scalar(value)
            pending_key = None
        else:
            pending_key = (indent, parent, key)

    return root


def read_branch_config(path: Path) -> list[str]:
    branches: list[str] = []

    for raw_line in path.read_text(encoding="utf-8").splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        branches.append(line)

    if len(branches) < 2:
        raise ValueError(f"{path} must contain at least two branches.")

    if len(set(branches)) != len(branches):
        raise ValueError(f"{path} contains duplicate branches.")

    return branches


def load_config(path: Path) -> dict:
    if path.exists():
        cfg = read_simple_yaml(path)
        branches = cfg.get("branches")
        if not isinstance(branches, list) or not all(isinstance(branch, str) for branch in branches):
            raise ValueError(f"{path} must define a 'branches' list.")

        base_branch = cfg.get("base_branch") or branches[0]
        if not isinstance(base_branch, str):
            raise ValueError(f"{path} base_branch must be a string.")

        return {
            "branches": branches,
            "base_branch": base_branch,
            "notifications": cfg.get("notifications") or {},
        }

    if LEGACY_BRANCH_FILE.exists():
        branches = read_branch_config(LEGACY_BRANCH_FILE)
        return {
            "branches": branches,
            "base_branch": branches[0],
            "notifications": {},
        }

    return {
        "branches": DEFAULT_BRANCHES,
        "base_branch": DEFAULT_BRANCHES[0],
        "notifications": {},
    }


def load_branches(args: argparse.Namespace) -> list[str]:
    if args.branches:
        branches = args.branches
    elif args.branch_file and args.branch_file.exists():
        branches = read_branch_config(args.branch_file)
    elif os.environ.get("FORWARD_MERGE_BRANCHES"):
        branches = os.environ["FORWARD_MERGE_BRANCHES"].split()
    else:
        branches = load_config(args.config_file)["branches"]

    if len(branches) < 2:
        raise ValueError("At least two branches are required.")

    if len(set(branches)) != len(branches):
        raise ValueError("Branch list contains duplicates.")

    return branches


def load_base_branch(args: argparse.Namespace, branches: list[str]) -> str:
    if args.base_branch:
        return args.base_branch

    cfg = load_config(args.config_file)
    base_branch = cfg.get("base_branch") or branches[0]
    if not isinstance(base_branch, str):
        raise ValueError("Configured base_branch must be a string.")

    return base_branch
